import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_tool',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            // @ts-expect-error - testing invalid schema
            properties: {location: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_tool/);
  });

  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect(executorCalls).toBe(0);
    expect(response.result).toContain('location');
    expect(response.result.toLowerCase()).toContain('required');
  });

  it('rejects a wrong-typed property naming the field and expected type without leaking the offending value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'ssn_lookup',
        description: 'Look up record by identifier',
        inputSchema: {
          type: 'object',
          properties: {ssn: {type: 'string'}},
          required: ['ssn'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('ssn_lookup', {ssn: 123456789});

    expect(executorCalls).toBe(0);
    expect(response.result).toContain('ssn');
    expect(response.result).toContain('string');
    expect(response.result).not.toContain('123456789');
  });
});

